def get_planet_sign_interpretation(planet_name: str, sign: str) -> str:
    """Easy to edit lookup."""
    sign_key = sign[:3] if sign else ""
    planet_dict = PLANET_SIGN_INTERPS.get(planet_name, {})
    if sign_key in planet_dict:
        return planet_dict[sign_key]
    # Generic fallback
    return f"{planet_name} in {sign} activates {planet_name.lower()}-ruled qualities through a {sign.lower()} lens. (Add specific interpretation in interpretations.py)"

def get_planet_house_interpretation(planet_name: str, house: int) -> str:
    if planet_name in PLANET_HOUSE_INTERPS and house in PLANET_HOUSE_INTERPS[planet_name]:
        return PLANET_HOUSE_INTERPS[planet_name][house]
    return f"In the {house}th house, {planet_name} directs its energy toward matters of identity, resources, communication, home, creativity, work, relationships, transformation, philosophy, career, community, or the subconscious (house {house}). (Customize in interpretations.py)"

def get_aspect_interpretation(p1: str, p2: str, aspect_type: str) -> str:
    key = (p1, p2, aspect_type.lower())
    # Add specific if you have them in a SPECIFIC dict
    # For now use general
    return ASPECT_GENERAL.get(aspect_type.lower(), f"The {aspect_type} between {p1} and {p2} combines their energies in a {aspect_type} way.")

def get_retrograde_note(planet_name: str) -> str:
    notes = {
        "Mercury": "Mercury retrograde in the natal chart often indicates a person who thinks deeply and may have a non-linear or revisiting style of learning and communicating. There can be a karmic feel to communication lessons.",
        "Venus": "Venus retrograde suggests a need to review values, relationships, and self-worth from within. Relationships may be more private or the person learns love through introspection.",
        "Mars": "Mars retrograde can indicate internalized drive or anger that needs conscious direction. Action may be more thoughtful or there are delays in asserting desires.",
    }
    return notes.get(planet_name, f"{planet_name} retrograde suggests the energy of this planet is turned inward or needs special conscious integration and review in this lifetime.")
